import React, { useState, useEffect } from 'react';
import { Line } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, Filler } from 'chart.js';
import { prediksiAPI, energyAPI } from '../services/api';
import { format, parseISO } from 'date-fns';
import { id } from 'date-fns/locale';
import { TrendingUp, Brain, RefreshCw, Calendar, DollarSign } from 'lucide-react';
import { formatRupiah, formatKWh } from '../utils/format';
import { toast } from 'react-toastify';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, Filler);

const PrediksiPage = () => {
  const [predictions, setPredictions] = useState([]);
  const [comparison, setComparison] = useState({ actual: [], predictions: [] });
  const [loading, setLoading] = useState(true);
  const [generating, setGenerating] = useState(false);

  const loadData = async () => {
    try {
      const [predRes, compRes] = await Promise.all([
        prediksiAPI.getLatest(),
        prediksiAPI.getComparison(30),
      ]);
      setPredictions(predRes.data);
      setComparison(compRes.data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadData(); }, []);

  const handleGenerate = async () => {
    setGenerating(true);
    toast.info('Memulai proses prediksi LSTM...');
    try {
      const res = await prediksiAPI.generate();
      toast.success('Prediksi berhasil dibuat!');
      await loadData();
    } catch (err) {
      const errMsg = err.response?.data?.error || 'Gagal membuat prediksi';
      toast.error(errMsg);
    } finally {
      setGenerating(false);
    }
  };

  // Build comparison chart data
  const compActualLabels = comparison.actual.map(d => format(parseISO(d.tanggal), 'dd/MM'));
  const compPredLabels = comparison.predictions.map(d => format(parseISO(d.tanggal_prediksi), 'dd/MM'));
  const allLabels = [...new Set([...compActualLabels, ...compPredLabels])];

  const comparisonData = {
    labels: allLabels,
    datasets: [
      {
        label: 'Aktual (kWh)',
        data: comparison.actual.map(d => d.total_energi),
        borderColor: '#22d3ee',
        backgroundColor: 'rgba(34, 211, 238, 0.1)',
        borderWidth: 2,
        pointRadius: 3,
        tension: 0.4,
        fill: false,
      },
      {
        label: 'Prediksi (kWh)',
        data: comparison.predictions.map(d => d.prediksi_energi),
        borderColor: '#f59e0b',
        backgroundColor: 'rgba(245, 158, 11, 0.1)',
        borderWidth: 2,
        borderDash: [5, 5],
        pointRadius: 3,
        tension: 0.4,
        fill: false,
      }
    ]
  };

  // Prediction chart for next 7 days
  const pred7Labels = predictions.map(d => format(parseISO(d.tanggal_prediksi), 'EEE dd/MM', { locale: id }));
  const pred7Data = {
    labels: pred7Labels,
    datasets: [
      {
        label: 'Prediksi Energi (kWh)',
        data: predictions.map(d => d.prediksi_energi),
        borderColor: '#3b82f6',
        backgroundColor: 'rgba(59, 130, 246, 0.2)',
        borderWidth: 2.5,
        pointRadius: 5,
        pointBackgroundColor: '#3b82f6',
        tension: 0.3,
        fill: true,
      },
      {
        label: 'Confidence Upper',
        data: predictions.map(d => d.confidence_upper),
        borderColor: 'rgba(59, 130, 246, 0.3)',
        backgroundColor: 'transparent',
        borderWidth: 1,
        borderDash: [3, 3],
        pointRadius: 0,
        tension: 0.3,
      },
      {
        label: 'Confidence Lower',
        data: predictions.map(d => d.confidence_lower),
        borderColor: 'rgba(59, 130, 246, 0.3)',
        backgroundColor: 'rgba(59, 130, 246, 0.05)',
        borderWidth: 1,
        borderDash: [3, 3],
        pointRadius: 0,
        tension: 0.3,
        fill: '-1',
      }
    ]
  };

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'top',
        labels: { color: '#94a3b8', font: { size: 11 }, padding: 16 }
      },
      tooltip: {
        backgroundColor: 'rgba(15, 23, 42, 0.95)',
        titleColor: '#94a3b8',
        bodyColor: '#e2e8f0',
        borderColor: 'rgba(59, 130, 246, 0.3)',
        borderWidth: 1,
      }
    },
    scales: {
      x: { grid: { color: 'rgba(255,255,255,0.04)' }, ticks: { color: '#475569', font: { size: 10 } } },
      y: { grid: { color: 'rgba(255,255,255,0.04)' }, ticks: { color: '#475569', font: { size: 10 } } }
    }
  };

  const totalPredEnergy = predictions.reduce((a, b) => a + b.prediksi_energi, 0);
  const totalPredBiaya = predictions.reduce((a, b) => a + b.prediksi_biaya, 0);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-display font-bold text-white">Prediksi Energi</h1>
          <p className="text-slate-400 text-sm mt-0.5">Prediksi konsumsi menggunakan algoritma LSTM</p>
        </div>
        <button
          onClick={handleGenerate}
          disabled={generating}
          className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-blue-600 to-cyan-600 hover:from-blue-500 hover:to-cyan-500 text-white rounded-xl font-medium text-sm transition-all shadow-lg shadow-blue-600/30 disabled:opacity-60"
        >
          {generating ? (
            <svg className="animate-spin h-4 w-4" viewBox="0 0 24 24" fill="none">
              <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
              <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
            </svg>
          ) : <Brain className="w-4 h-4" />}
          {generating ? 'Memproses...' : 'Generate Prediksi'}
        </button>
      </div>

      {/* Summary cards for next 7 days */}
      {predictions.length > 0 && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <div className="bg-slate-900/60 border border-slate-700/40 rounded-2xl p-4 col-span-2">
            <div className="flex items-center gap-2 mb-3">
              <TrendingUp className="w-4 h-4 text-blue-400" />
              <p className="text-slate-400 text-sm">Total Prediksi 7 Hari</p>
            </div>
            <p className="text-2xl font-bold text-white font-mono">{formatKWh(totalPredEnergy)} <span className="text-slate-400 text-base font-normal">kWh</span></p>
          </div>
          <div className="bg-slate-900/60 border border-slate-700/40 rounded-2xl p-4 col-span-2">
            <div className="flex items-center gap-2 mb-3">
              <DollarSign className="w-4 h-4 text-emerald-400" />
              <p className="text-slate-400 text-sm">Estimasi Biaya 7 Hari</p>
            </div>
            <p className="text-2xl font-bold text-white font-mono">{formatRupiah(totalPredBiaya)}</p>
          </div>
        </div>
      )}

      {/* 7-day prediction chart */}
      <div className="bg-slate-900/60 border border-slate-700/40 rounded-2xl p-5">
        <div className="flex items-center gap-2 mb-4">
          <Calendar className="w-4 h-4 text-blue-400" />
          <h3 className="text-white font-semibold">Prediksi 7 Hari ke Depan</h3>
        </div>
        {loading ? (
          <div className="h-60 flex items-center justify-center">
            <div className="w-8 h-8 border-2 border-blue-500 border-t-transparent rounded-full animate-spin" />
          </div>
        ) : predictions.length === 0 ? (
          <div className="h-60 flex flex-col items-center justify-center text-slate-400">
            <Brain className="w-12 h-12 mb-3 opacity-30" />
            <p>Belum ada prediksi</p>
            <p className="text-sm text-slate-500 mt-1">Klik "Generate Prediksi" untuk memulai</p>
          </div>
        ) : (
          <div className="h-60">
            <Line data={pred7Data} options={chartOptions} />
          </div>
        )}
      </div>

      {/* Prediction table */}
      {predictions.length > 0 && (
        <div className="bg-slate-900/60 border border-slate-700/40 rounded-2xl overflow-hidden">
          <div className="p-4 border-b border-slate-800">
            <h3 className="text-white font-semibold text-sm">Tabel Prediksi Harian</h3>
          </div>
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-slate-800/40">
                {['Tanggal', 'Prediksi Energi (kWh)', 'Batas Bawah', 'Batas Atas', 'Estimasi Biaya'].map(h => (
                  <th key={h} className="text-left px-4 py-3 text-xs font-semibold text-slate-400 uppercase tracking-wide">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {predictions.map((row, idx) => (
                <tr key={idx} className="border-t border-slate-800/40 hover:bg-slate-800/20 transition-colors">
                  <td className="px-4 py-3 text-slate-300">
                    {format(parseISO(row.tanggal_prediksi), 'EEEE, dd MMMM yyyy', { locale: id })}
                  </td>
                  <td className="px-4 py-3 text-blue-400 font-mono font-semibold">{row.prediksi_energi.toFixed(4)}</td>
                  <td className="px-4 py-3 text-slate-400 font-mono">{row.confidence_lower?.toFixed(4)}</td>
                  <td className="px-4 py-3 text-slate-400 font-mono">{row.confidence_upper?.toFixed(4)}</td>
                  <td className="px-4 py-3 text-emerald-400 font-mono">{formatRupiah(row.prediksi_biaya)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Comparison chart */}
      <div className="bg-slate-900/60 border border-slate-700/40 rounded-2xl p-5">
        <h3 className="text-white font-semibold mb-4">Perbandingan Data Aktual vs Prediksi (30 Hari)</h3>
        <div className="h-64">
          {loading ? (
            <div className="flex items-center justify-center h-full">
              <div className="w-8 h-8 border-2 border-blue-500 border-t-transparent rounded-full animate-spin" />
            </div>
          ) : (
            <Line data={comparisonData} options={chartOptions} />
          )}
        </div>
      </div>
    </div>
  );
};

export default PrediksiPage;
